insert into community.challenges (id, topic, difficulty, weekly, question, options, answer, explanation) values
('d01','Programming','beginner',false,'In Python, what does len([3, 1, 4]) return?',array['3','8','4','An error'],0,'len() counts the items in a list. [3, 1, 4] has three items.'),
('d02','Networking','beginner',false,'Which device forwards packets between different networks?',array['Switch','Router','Hub','Repeater'],1,'A router reads IP addresses and moves packets between networks. A switch works inside one network.'),
('d03','Cybersecurity','beginner',false,'What is phishing?',array['A fake message that tricks you into giving away information','A way to speed up Wi-Fi','A type of firewall','A backup method'],0,'Phishing uses fake emails, texts or sites to steal passwords or personal data.'),
('d04','Databases','beginner',false,'Which SQL keyword picks rows that match a condition?',array['ORDER BY','WHERE','GROUP BY','JOIN'],1,'WHERE filters rows, for example SELECT * FROM users WHERE age > 18.'),
('d05','Hardware','beginner',false,'Which component temporarily holds data the CPU is working on?',array['Hard drive','RAM','Power supply','GPU fan'],1,'RAM is fast, temporary memory. Its contents are lost when the power goes off.'),
('d06','Programming','beginner',false,'What is the result of 7 // 2 in Python?',array['3.5','3','4','1'],1,'// is floor division: it divides and drops the remainder, so 7 // 2 is 3.'),
('d07','Networking','intermediate',false,'Which port does HTTPS use by default?',array['80','21','443','25'],2,'HTTPS uses TCP port 443. Plain HTTP uses port 80.'),
('d08','AI','beginner',false,'What does a machine learning model learn from?',array['Data','Electricity','Screen brightness','The keyboard layout'],0,'Models find patterns in training data, then use them to make predictions on new data.'),
('d09','Logic','beginner',false,'If all routers are devices and some devices are wireless, which statement must be true?',array['All routers are wireless','Some routers are wireless','All routers are devices','No routers are wireless'],2,'Only the first fact is certain. The second says nothing about which devices are wireless.'),
('d10','Cybersecurity','intermediate',false,'What does two-factor authentication add?',array['A second password field','A second proof of identity, like a code on your phone','A faster login','A backup email'],1,'2FA combines something you know (password) with something you have or are (phone, key, fingerprint).'),
('d11','Programming','intermediate',false,'In JavaScript, what does [1, 2, 3].map(x => x * 2) return?',array['[2, 4, 6]','6','[1, 2, 3, 2]','undefined'],0,'map() returns a new array with the function applied to every item.'),
('d12','Networking','beginner',false,'What does DNS do?',array['Encrypts traffic','Turns domain names into IP addresses','Assigns MAC addresses','Blocks viruses'],1,'DNS is the internet phone book: it finds the IP address for a name like example.com.'),
('d13','Databases','intermediate',false,'What is a primary key?',array['A column that uniquely identifies each row','The first column in a table','A password for the database','An index on every column'],0,'A primary key is unique and not null, so every row can be found exactly.'),
('d14','Hardware','intermediate',false,'What does SSD stand for?',array['Super Speed Disk','Solid State Drive','System Storage Device','Serial Storage Disk'],1,'SSDs store data in flash memory with no moving parts, so they are faster than hard disks.'),
('d15','Programming','beginner',false,'Which of these is a loop in most languages?',array['if','for','return','class'],1,'for repeats a block of code. if makes a decision, it does not repeat.'),
('d16','Cybersecurity','beginner',false,'Which password is strongest?',array['password123','Summer2026','correct-horse-battery-staple-91','qwerty'],2,'Length matters most. A long passphrase of random words is hard to guess and easy to remember.'),
('d17','Networking','intermediate',false,'How many bits are in an IPv4 address?',array['16','32','64','128'],1,'IPv4 addresses are 32 bits, written as four numbers from 0 to 255. IPv6 uses 128 bits.'),
('d18','AI','intermediate',false,'What is overfitting?',array['A model that learns the training data too closely and does badly on new data','A model that is too small to run','Using too much RAM','Training on a GPU'],0,'An overfit model memorises its training examples instead of learning general patterns.'),
('d19','Programming','intermediate',false,'What is the time complexity of binary search on a sorted list?',array['O(n)','O(log n)','O(n²)','O(1)'],1,'Each step halves the search space, so it takes about log₂(n) steps.'),
('d20','Logic','intermediate',false,'What is 1011 in binary as a decimal number?',array['9','10','11','13'],2,'1011 = 8 + 0 + 2 + 1 = 11.'),
('d21','Cybersecurity','intermediate',false,'What does HTTPS protect?',array['Data travelling between your browser and the website','Your computer from all viruses','Your Wi-Fi password','Files on your hard drive'],0,'HTTPS encrypts traffic in transit. It does not make the website itself trustworthy.'),
('d22','Databases','beginner',false,'Which of these is a database?',array['PostgreSQL','Photoshop','Chrome','Windows'],0,'PostgreSQL is an open-source relational database.'),
('d23','Networking','beginner',false,'What does Wi-Fi use to carry data?',array['Radio waves','Copper cables','Sound waves','Light through fibre'],0,'Wi-Fi sends data over radio, usually in the 2.4 GHz, 5 GHz or 6 GHz bands.'),
('d24','Programming','beginner',false,'What does HTML do on a web page?',array['Describes the structure and content','Styles colours and layout','Stores passwords','Runs the server'],0,'HTML gives a page its structure. CSS styles it and JavaScript makes it interactive.'),
('d25','Hardware','beginner',false,'Which is an input device?',array['Monitor','Printer','Keyboard','Speaker'],2,'Input devices send data into the computer. Monitors, printers and speakers are outputs.'),
('d26','AI','beginner',false,'Which task is a good fit for image classification?',array['Telling cats from dogs in photos','Sorting a list of numbers','Sending an email','Compressing a ZIP file'],0,'Image classification assigns a label to a picture.'),
('d27','Logic','beginner',false,'A loop starts at 0 and stops before 5, counting up by 1. How many times does it run?',array['4','5','6','0'],1,'It runs for 0, 1, 2, 3 and 4: five times.'),
('d28','Cybersecurity','advanced',false,'What does a hash function used for passwords need to be?',array['Reversible','Fast to compute and easy to reverse','One-way and slow to brute-force','Encrypted with the user’s email'],2,'Password hashes (bcrypt, Argon2) are one-way and deliberately slow, so stolen hashes are hard to crack.'),
('w01','Programming','intermediate',true,'What does this Python print?  x = [1, 2]; y = x; y.append(3); print(x)',array['[1, 2]','[1, 2, 3]','[3]','An error'],1,'y = x does not copy the list: both names point to the same list, so appending through y changes x too.'),
('w02','Networking','advanced',true,'How many usable host addresses are in a /26 IPv4 subnet?',array['62','64','30','126'],0,'/26 leaves 6 host bits: 2⁶ = 64 addresses, minus the network and broadcast addresses = 62.'),
('w03','Databases','intermediate',true,'Which JOIN returns every row from the left table, even with no match on the right?',array['INNER JOIN','LEFT JOIN','CROSS JOIN','SELF JOIN'],1,'LEFT JOIN keeps all left rows and fills missing right-side columns with NULL.'),
('w04','Cybersecurity','intermediate',true,'Which attack puts code into a database query through user input?',array['Phishing','SQL injection','DDoS','Shoulder surfing'],1,'SQL injection happens when input is pasted into a query. Parameterised queries prevent it.'),
('w05','AI','advanced',true,'Why do we split data into training and test sets?',array['To train faster','To measure how the model does on data it has not seen','To use less memory','Because models need two files'],1,'The test set estimates real-world performance and reveals overfitting.'),
('w06','Logic','advanced',true,'You have 8 coins, one heavier. What is the fewest weighings on a balance scale that always finds it?',array['1','2','3','4'],1,'Weigh 3 against 3. If balanced, weigh the last 2. If not, weigh 1 against 1 from the heavier group of 3.')
